import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { signupHandler } from "../handlers/signupHandler";
import type { ApiError } from "../runtime/client";
import type { SignupRequest } from "../types/SignupRequest";

type Data = Awaited<ReturnType<typeof signupHandler>>;
type Vars = SignupRequest;

export function useSignup(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => signupHandler(vars),
    ...options,
  });
}
